                                                                                                                                                                                                             
  CREATE TABLE "STS_FOLDER"                                                                                                                                                                        
   (	"FOLDER_ID" NUMBER(20,0) GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,     
	"FOLDER_LIB_ID" NUMBER(20,0),                                                                                                                                                                               
	"FOLDER_NAME" VARCHAR2(500),                                                                                                                                                                                
	"FOLDER_FORMAT" VARCHAR2(50),                                                                                                                                                                               
	"FOLDER_STATUS" VARCHAR2(255) DEFAULT 1,                                                                                                                                                                    
	"FOLDER_URL" VARCHAR2(2000),                                                                                                                                                                                
	"DEL_FLAG" NUMBER(1,0) DEFAULT 0,                                                                                                                                                                           
	"DEL_DATE" DATE,                                                                                                                                                                                            
	"UPLOAD_DATE" DATE,                                                                                                                                                                                         
	"PLANS_FILE_TYPE" NUMBER(1,0),                                                                                                                                                                              
	"PLANS_FILE_DATE" DATE,                                                                                                                                                                                     
	"REMARK" VARCHAR2(500),                                                                                                                                                                                     
	"TENANT_ID" NUMBER(20,0),                                                                                                                                                                                   
	"CREATED_BY" NUMBER(20,0),                                                                                                                                                                                  
	"CREATION_DATE" DATE DEFAULT sysdate,                                                                                                                                                                       
	"UPDATED_BY" NUMBER(20,0),                                                                                                                                                                                  
	"UPDATE_DATE" DATE DEFAULT sysdate,                                                                                                                                                                         
	"SCOPE_TYPE" NVARCHAR2(20),                                                                                                                                                                                 
	"FOLDER_ID_OLD" NUMBER(20,0),                                                                                                                                                                               
	"FOLDER_CONTENT" CLOB,                                                                                                                                                                                      
	"FILE_SIZE" NUMBER(20,0),                                                                                                                                                                                   
	"SYSTEM_ID" NUMBER(20,0),                                                                                                                                                                                   
	"SORT_NUM" NUMBER(10,0),                                                                                                                                                                                    
	 PRIMARY KEY ("FOLDER_ID")                                                                                                                                                                                  
  USING INDEX  ENABLE                                                                                                                                                                                        
   ) ;                                                                                                                                                                                                       

